            reversed: '古い利権にしがみつく役員どもと、分け前に不満を持つ現場の従業員の間で板挟みになっている。くだらん組織内の揉め事に巻き込まれて自分のリソースを失う前に、一度距離を置いて冷徹に状況を観察しな。'
