const VERDICT_BANDS = ['critical', 'warning', 'mixed', 'favorable', 'excellent'];

function mapSubtopicVerdicts(rows) {
    return Object.fromEntries(rows.map(([staff, line], index) => [VERDICT_BANDS[index], { staff, line }]));
}

